import { signal } from "@rivetjs/reactivity";
import { Router, defineRoute, For, lazyComponent, clientOnly } from "@rivetjs/runtime/dom";
import type { BrowserRouter } from "@rivetjs/runtime/router/dom";
import { Services, type Item } from "./context.js";

const Detail = lazyComponent(() => import("./routes/detail.js"), undefined, {
  fallback: () => <p role="status">Loading detail view…</p>,
});
const BrowserWidget = clientOnly(() => import("./browser-widget.js"), undefined, {
  fallback: () => <p class="text-sm text-slate-500">Browser tools load in the browser.</p>,
});
interface AppProps {
  router: Pick<BrowserRouter, "location"> & Partial<Pick<BrowserRouter, "navigate">>;
  interactive?: boolean;
}
/** Shared application. Resumed pages are interactive (client navigation); plain SSR keeps ordinary links. */
export function App({ router, interactive = false }: AppProps) {
  const count = signal(0);
  const follow = (event: MouseEvent, href: string) => {
    if (
      !interactive ||
      !router.navigate ||
      event.button !== 0 ||
      event.metaKey ||
      event.ctrlKey ||
      event.shiftKey ||
      event.altKey
    )
      return;
    event.preventDefault();
    router.navigate(href);
  };
  const routes = [
    defineRoute("/", {
      load(work) {
        const services = work.get(Services);
        if (!services) throw Error("App requires a Services provider");
        return services.list(work.signal);
      },
      render(items) {
        return <List items={items} interactive={interactive} follow={follow} />;
      },
    }),
    defineRoute("/items/:id", {
      load(work, match) {
        const services = work.get(Services);
        if (!services) throw Error("App requires a Services provider");
        return services.detail(match.params.id, work.signal);
      },
      render(item) {
        return item ? (
          <Detail item={item} home="/" follow={follow} />
        ) : (
          <p role="status">
            Example not found.{" "}
            <a href="/" onClick={(event) => follow(event, "/")}>
              Back to examples
            </a>
          </p>
        );
      },
    }),
  ];
  return (
    <main class="mx-auto max-w-3xl px-6 py-12 text-slate-900">
      <header class="mb-10 border-b border-slate-200 pb-8">
        <p class="mb-3 text-sm font-semibold uppercase tracking-widest text-teal-700">
          Compiled views · explicit ownership
        </p>
        <h1 class="text-4xl font-bold tracking-tight">Rivet playground</h1>
        <p class="mt-4 max-w-xl text-base leading-7 text-slate-600">
          One small application, rendered on the server and resumed in the browser. Data, ownership, and cancellation
          stay explicit.
        </p>
      </header>
      <section class="mb-8 rounded-xl border border-slate-200 bg-white p-5" aria-labelledby="counter-title">
        <h2 id="counter-title" class="text-lg font-semibold">
          Owned state
        </h2>
        <p class="mt-2 text-sm text-slate-600">The browser counter updates without replacing the surrounding page.</p>
        <div class="mt-4 flex items-center gap-4">
          <button
            class="rounded-md bg-teal-700 px-4 py-2 text-sm font-semibold text-white disabled:opacity-50"
            type="button"
            disabled={!interactive}
            onClick={() => count.update((value) => value + 1)}
          >
            Increase count
          </button>
          <output id="count" aria-live="polite" class="font-mono text-lg">
            {count()}
          </output>
        </div>
      </section>
      <Router
        router={router}
        routes={routes}
        fallback={() => <p role="status">Loading examples…</p>}
        error={(cause) => (
          <p role="alert">Could not load examples: {cause instanceof Error ? cause.message : "unknown error"}</p>
        )}
        notFound={() => <p role="status">Page not found.</p>}
      />
      <footer class="mt-10 border-t border-slate-200 pt-5">
        <BrowserWidget />
      </footer>
    </main>
  );
}

function List({
  items,
  interactive,
  follow,
}: {
  items: Item[];
  interactive: boolean;
  follow: (event: MouseEvent, href: string) => void;
}) {
  const query = signal("");
  return (
    <section aria-labelledby="examples-title">
      <h2 id="examples-title" class="text-2xl font-semibold">
        Explore the examples
      </h2>
      <label for="filter" class="mt-5 block text-sm font-medium">
        Filter examples
      </label>
      <input
        id="filter"
        class="mt-2 w-full rounded-md border border-slate-300 bg-white px-3 py-2"
        type="search"
        model:value={query}
        readOnly={!interactive}
        placeholder={interactive ? "Search by title" : "Filtering needs the resumed production page"}
      />
      <ul id="examples" class="mt-5 grid gap-3">
        <For
          each={() => items.filter((item) => item.title.toLowerCase().includes(query().toLowerCase()))}
          by={(item) => item.id}
        >
          {(item) => (
            <li class="rounded-xl border border-slate-200 bg-white p-5">
              <a
                class="font-semibold text-teal-700 underline underline-offset-4"
                href={"/items/" + encodeURIComponent(item().id)}
                onClick={(event) => follow(event, "/items/" + encodeURIComponent(item().id))}
              >
                {item().title}
              </a>
              <p class="mt-2 text-sm leading-6 text-slate-600">{item().description}</p>
            </li>
          )}
        </For>
      </ul>
    </section>
  );
}

import type { Item } from "../context.js";

/** Deferred detail view shared by server lazy loading and the browser's route chunk. */
export default function Detail({
  item,
  home,
  follow,
}: {
  item: Item;
  home: string;
  follow: (event: MouseEvent, href: string) => void;
}) {
  return (
    <article id="detail" class="rounded-xl border border-slate-200 bg-white p-6">
      <a
        class="text-sm font-semibold text-teal-700 underline underline-offset-4"
        href={home}
        onClick={(event) => follow(event, home)}
      >
        Back to examples
      </a>
      <h2 class="mt-6 text-2xl font-semibold">{item.title}</h2>
      <p class="mt-4 leading-7 text-slate-600">{item.description}</p>
      <p class="mt-6 text-sm text-slate-500">
        This view loads when its route is visited. Navigation cancels work owned by the previous route.
      </p>
    </article>
  );
}

import { signal, computed } from "@rivetjs/reactivity";
import { clientEffect, clientEvent } from "@rivetjs/runtime/dom";
import type { Item } from "./context.js";

/** Server-rendered, resumed in the browser without running this component there. */
export function ResumeDemo({ items }: { items: Item[] }) {
  const count = signal(0);
  const query = signal("");
  const titles = items.map((item) => item.title.toLowerCase());
  const matches = computed(() => titles.filter((title) => title.includes(query().toLowerCase())).length);
  const width = signal(0);
  let canvas!: HTMLCanvasElement;
  clientEvent(window, "resize", () => width.set(innerWidth));
  clientEffect(() => {
    const ctx = canvas.getContext("2d")!;
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = "#0f766e";
    ctx.fillRect(0, 0, Math.min(canvas.width, 12 * count()), canvas.height);
    canvas.dataset.drawn = String(count());
  });
  return (
    <main class="mx-auto max-w-3xl px-6 py-12 text-slate-900">
      <h1 class="text-4xl font-bold tracking-tight">Resumed page</h1>
      <p class="mt-4 text-base leading-7 text-slate-600">
        Rendered on the server. The browser runs only a small loader until you interact.
      </p>
      <section class="mt-8 rounded-xl border border-slate-200 bg-white p-5" aria-labelledby="resume-counter">
        <h2 id="resume-counter" class="text-lg font-semibold">
          Counter
        </h2>
        <div class="mt-4 flex items-center gap-4">
          <button
            id="resume-increase"
            class="rounded-md bg-teal-700 px-4 py-2 text-sm font-semibold text-white"
            type="button"
            onClick={() => count.update((value) => value + 1)}
          >
            Increase count
          </button>
          <output id="resume-count" aria-live="polite" class="font-mono text-lg">
            {count()}
          </output>
        </div>
        <canvas id="resume-canvas" class="mt-4 h-3 w-full" width={240} height={12} ref={(el) => (canvas = el)} />
      </section>
      <section class="mt-8" aria-labelledby="resume-filter-title">
        <h2 id="resume-filter-title" class="text-lg font-semibold">
          Filter
        </h2>
        <label for="resume-filter" class="mt-3 block text-sm font-medium">
          Filter examples
        </label>
        <input
          id="resume-filter"
          class="mt-2 w-full rounded-md border border-slate-300 bg-white px-3 py-2"
          type="search"
          model:value={query}
          placeholder="Search by title"
        />
        <p id="resume-matches" class="mt-3 text-sm text-slate-600">
          {matches()} of {titles.length} examples match
        </p>
        <p id="resume-width" class="mt-1 text-xs text-slate-500">
          Window width after resize: {width()}
        </p>
      </section>
    </main>
  );
}

import { clientEffect } from "@rivetjs/runtime/dom";
import type { BrowserRouter } from "@rivetjs/runtime/router/dom";

// Module scope: the dynamic import resolves against this file, and the analytics module stays its own
// chunk outside App's static graph (so App's preload strategy does not schedule it).
const loadAnalytics = () => import("./analytics.js");

/** gtag-style page views: the analytics chunk loads at idle and the effect reruns on each client
 * navigation through the router's location signal. Renders nothing. */
export function PageViews({ router }: { router: Pick<BrowserRouter, "location"> }) {
  clientEffect(
    async () => {
      const path = router.location().pathname;
      const { pageView } = await loadAnalytics();
      pageView(path);
    },
    { when: "idle" },
  );
  return null;
}

