/** Render application HTML with isolated URL/services and request cancellation. With a resume
 * manifest the page is interactive: state and the inline loader follow the content. */
export function render(
  url: URL | string,
  { signal, manifest }: { signal?: AbortSignal; manifest?: ResumeManifest } = {},
) {
  const page = () => {
    const router = createRouter(url);
    const services = createServerServices();
    return (
      <Provider token={Services} value={services}>
        <App router={router} interactive={Boolean(manifest)} />
        <PageViews router={router} />
      </Provider>
    );
  };
  return manifest ? resumableToString(page, { manifest, signal }) : renderToString(page, { signal });
}

